mapper.select:
SELECT FROM fee_bill
ORDER BY period DESC, id DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE fee_bill
owner_id = #{ownerId}, owner_name = #{ownerName}, house_id = #{houseId}, house_no = #{houseNo}, parking_id = #{parkingId}, parking_no = #{parkingNo}, fee_type = #{feeType}, fee_name = #{feeName}, period = #{period}, amount = #{amount}, paid_amount = #{paidAmount}, pay_status = #{payStatus}, due_date = #{dueDate}, pay_time = #{payTime}, pay_method = #{payMethod}, remark = #{remark},
WHERE id = #{id}

mapper.delete:
DELETE FROM fee_bill
WHERE period = #{period}
  AND fee_type = #{feeType}
  AND pay_status IN ('UNPAID', 'OVERDUE')

mapper.select:
SELECT COUNT(*) FROM fee_bill
WHERE owner_id = #{ownerId}
  AND period = #{period}
  AND fee_type = #{feeType}

    AND parking_id = #{parkingId}
    AND parking_id IS NULL
